#[cfg(test)]
mod blizzard59_development_tests {
    use super::*;
    fn catalog()->SpriteActionCatalog {SpriteActionCatalog::parse_for_inspection(&[b"11297 0 0\n".as_slice(),include_bytes!(r"D:\lineage開發\3-lito開發\lito重建版\驗證紀錄\current\native-E149-blizzard59-inspection\20261024-115029-671040\757.definition.txt")].concat(),super::super::sprite_actions::ActionLimits::default()).unwrap()}
    fn clip()->Clip {Clip::new(Arc::new(qualify(&catalog()).unwrap().remove(0).2)).unwrap()}
    fn origin()->WorldCell {WorldCell{x:100,y:100}}
    fn cue()->Cue {Cue{target_origin:None,attack:super::super::native_attack_many::Attack{action:18,caster:1,position:[100,100],heading:0,sequence:7,graphics:757,targets:vec![]},caster_incarnation:1,action_sequence:99,targets:vec![(2,true,Some(3)),(2,false,Some(3))]}}
    #[test]
    fn exact_twenty_five_positions_keep_native_order_and_root_last() {let c=Clock::new(origin(),&clip(),[0;25]).unwrap();let p:Vec<_>=c.nodes.iter().map(|n|[n.position.x-100,n.position.y-100]).collect();assert_eq!(p.len(),25);assert_eq!(p.iter().collect::<BTreeSet<_>>().len(),25);assert_eq!(&p[..4],&[[0,-5],[0,-3],[5,-5],[3,-3]]);assert_eq!(&p[16..],&[[0,-7],[7,-7],[7,0],[7,7],[0,7],[-7,7],[-7,0],[-7,-7],[0,0]]);}
    #[test]
    fn each_node_enters_sound_and_hit_once_without_collapsing_occurrences() {let mut c=Clock::new(origin(),&clip(),[0;25]).unwrap();let e=c.advance(0).unwrap();assert_eq!(e.len(),25);assert!(e.iter().all(|e|e.source==1&&e.callback==1&&e.event==FrameEvent::Sound(123)));assert!(c.advance(0).unwrap().is_empty());c.advance(125_000_000).unwrap();let e=c.advance(250_000_000).unwrap();assert_eq!(e.len(),25);assert!(e.iter().all(|e|e.source==3&&e.event==FrameEvent::Hit));assert_eq!(e.iter().filter(|e|e.node==24).count(),1);}
    #[test]
    fn independently_born_nodes_do_not_share_a_cursor_and_late_poll_does_not_catch_up() {let mut births=[0;25];births[24]=1_000_000;let mut c=Clock::new(origin(),&clip(),births).unwrap();c.advance(1_000_000).unwrap();c.advance(125_000_000).unwrap();assert_eq!((c.nodes[0].source,c.nodes[24].source),(2,1));let h=c.clone();c.advance(2_000_000_000).unwrap();assert_eq!((c.nodes[0].source,c.nodes[24].source),(3,2));let mut restored=h;restored.advance(2_000_000_000).unwrap();assert_eq!((restored.nodes[0].source,restored.nodes[24].source),(3,2));}
    #[test]
    fn terminal_zero_frame_dwells_and_invalid_time_or_position_is_rejected() {let mut c=Clock::new(origin(),&clip(),[0;25]).unwrap();for n in 0..23{c.advance(n*125_000_000).unwrap();}assert_eq!(c.nodes[0].source,0);assert!(!c.finished());c.advance(2_875_000_000).unwrap();assert!(c.finished());assert!(c.advance(2_874_000_000).is_err());assert!(Clock::new(WorldCell{x:i32::MAX,y:0},&clip(),[0;25]).is_err());assert!(Clock::new(origin(),&clip(),[1;25]).unwrap().advance(0).is_err());}
    #[test]
    fn source_retirement_preserves_admission_but_drops_graph_and_active_audio_keys() {let mut stage=Stage::default();stage.history=History{generation:Some(4),seen:BTreeSet::from([(1,99)]),active:vec![Cast{cue:cue(),clock:Clock::new(origin(),&clip(),[0;25]).unwrap(),finished:false}],started:1,omitted:0};let h=stage.history();assert_eq!(h.active_sequences(),BTreeSet::from([99]));let mut restored=Stage::default();restored.restore(h.clone(),true);assert_eq!(restored.active_casts(),1);restored.restore(h,false);assert_eq!(restored.active_casts(),0);assert!(restored.history.seen.contains(&(1,99)));assert!(restored.history.active_sequences().is_empty());let mut stale=History{generation:Some(5),..Default::default()};stale.merge_admission(&restored.history);assert!(stale.seen.is_empty());}
    #[test]
    fn group_projection_and_fragment_budget_fail_before_any_submission() {let frame=super::super::sprite::SpriteFrame{fragments:Some(super::super::sprite::SpriteFrameFragments{references:vec![],atlas:Arc::new(vec![])}),x_offset:0,y_offset:0,width:0,height:0,frame_type:0,unknown1:0,unknown2:0,rgba:vec![]};let view=ViewProjection{anchor_cell:origin(),anchor_pixel:super::super::world_map::PixelPoint{x:0,y:0}};let mut q=vec![];for _ in 0..488{q.push(super::super::native_world_effects::Effect{frame:&frame,position:origin(),mix:Mix::Screen});}assert!(submit_group(&mut Target::Fragments(&mut q),&vec![(&frame,origin());25],view).is_err());assert_eq!(q.len(),488);q.clear();assert!(submit_group(&mut Target::Fragments(&mut q),&[(&frame,origin()),(&frame,WorldCell{x:i32::MAX,y:i32::MIN})],view).is_err());assert!(q.is_empty());submit_group(&mut Target::Fragments(&mut q),&vec![(&frame,origin());25],view).unwrap();assert_eq!(q.len(),25);}
    #[test]
    fn shared_definition_rejects_changed_sound_duration_hit_or_mix() {let bytes=[b"11297 0 0\n".as_slice(),include_bytes!(r"D:\lineage開發\3-lito開發\lito重建版\驗證紀錄\current\native-E149-blizzard59-inspection\20261024-115029-671040\757.definition.txt")].concat();let text=String::from_utf8(bytes).unwrap();for(a,b)in[("[123","[124"),("0.0:3","0.0:4"),("0.2:3!","0.2:3"),("104.attr(8)","104.attr(128)")]{assert!(text.contains(a));let c=SpriteActionCatalog::parse_for_inspection(text.replace(a,b).as_bytes(),super::super::sprite_actions::ActionLimits::default()).unwrap();assert!(qualify(&c).is_err());}}
    #[test]
    #[ignore="LITO_SHARED_RESOURCE_ROOT; original757/123, 25 memory fragments and history only; no desktop/audio playback"]
    fn original_bank_draws_twenty_five_and_keeps_callbacks_after_actor_and_ring_leave() {let root:std::path::PathBuf=std::env::var_os("LITO_SHARED_RESOURCE_ROOT").expect("explicit shared root").into();let cancel=AtomicBool::new(false);let mut w=super::super::native_login::LoginController::default().snapshot().world.clone();let f:Value=serde_json::from_slice(include_bytes!(r"D:\lineage開發\3-lito開發\lito重建版\LiTo381-Modern\tests\fixtures\native-world-current.json")).unwrap();for key in ["world","start","status","actor","bot"]{let h=f["packets"][key].as_str().unwrap();w.accept(&(0..h.len()).step_by(2).map(|i|u8::from_str_radix(&h[i..i+2],16).unwrap()).collect::<Vec<_>>()).unwrap();}let own=w.own_actor().unwrap().clone();let mut c=cue();c.attack.caster=own.id;c.caster_incarnation=own.incarnation;c.attack.position=[own.x,own.y];w.many_attacks.push(c.clone());w.learned_skills.insert(59);let event=EnteredEvent{actor:own.id,sequence:99,action:18,frame:1,event:"Hit".into(),sound:None,prepared_audio:None};let mut stage=Stage::default();stage.prepare(&root,&w,&cancel,&mut None);assert!(stage.error.is_none());stage.update(&w,[&event].into_iter(),0,0);let view=ViewProjection{anchor_cell:WorldCell{x:i32::from(own.x),y:i32::from(own.y)},anchor_pixel:super::super::world_map::PixelPoint{x:400,y:300}};let mut fragments=vec![];let(row,audio)=stage.draw_to(&mut Target::Fragments(&mut fragments),view);assert_eq!(row["started"],1);assert_eq!(fragments.len(),25);assert_eq!(audio.len(),25);assert!(audio.iter().all(|e|e.actor==0&&e.prepared_audio.is_some()));drop(fragments);let h=stage.history();w.actors.clear();w.many_attacks.clear();w.learned_skills.clear();let before=serde_json::to_value(&w).unwrap();let mut restored=Stage::default();restored.restore(h,true);restored.prepare(&root,&w,&cancel,&mut None);restored.update(&w,std::iter::empty(),125_000_000,0);restored.update(&w,std::iter::empty(),250_000_000,0);assert_eq!(restored.diagnostics.len(),25);assert_eq!(restored.diagnostics.iter().filter(|d|d["root_target_list"]==true).count(),1);assert_eq!(serde_json::to_value(&w).unwrap(),before);w.many_attacks.push(c);restored.update(&w,[&event].into_iter(),250_000_000,0);assert_eq!(restored.history.started,1);}
}
